<template>
  <AppShell>
    <main class="diseno-page">
      <header class="page-header"><div><h1>Diseño de impresión</h1></div><div class="page-actions"><button class="restablecer" :disabled="guardando || cargando" @click="restablecerPredeterminado">Restablecer diseño actual</button><button class="imprimir-prueba" :disabled="cargando" @click="imprimirPrueba">Imprimir prueba</button><button class="guardar" :disabled="guardando || cargando" @click="guardarDiseno">{{ guardando ? 'Guardando…' : 'Guardar diseño' }}</button></div></header>
      <nav class="tabs"><button :class="{ activo: vista === 'ticket' }" @click="vista = 'ticket'">Ticket de orden</button><button :class="{ activo: vista === 'prendas' }" @click="vista = 'prendas'">Etiqueta de prendas</button></nav>
      <p v-if="error" class="error">{{ error }}</p><p v-if="exito" class="exito">Diseño guardado en la base de datos. La impresión ya usará esta configuración.</p>
      <div class="editor-grid">
        <section class="panel controles"><h2>{{ vista === 'ticket' ? 'Diseño del ticket' : 'Diseño de prendas' }}</h2>
          <label>Impresora y ancho de papel<select v-model.number="diseno.ancho"><option :value="58">Bluetooth compacta · 58 mm</option><option :value="72">Térmica compacta · 72 mm</option><option :value="80">Térmica estándar · 80 mm</option></select></label>
          <label>Tamaño de texto <output>{{ diseno.tamanoFuente }} px</output><input v-model.number="diseno.tamanoFuente" type="range" min="8" max="16" /></label>
          <h3>Imagen y contenido</h3>
          <div class="selector-imagen"><img :src="diseno.logoUrl || logoTicket" alt="Vista miniatura del logo" class="miniatura-logo" /><label class="subida-imagen"><span>{{ diseno.logoUrl ? 'Cambiar imagen' : 'Elegir imagen' }}</span><input type="file" accept="image/*" :disabled="subiendoImagen" @change="subirLogo" /><small>{{ subiendoImagen ? 'Subiendo a Cloudinary…' : diseno.logoUrl ? 'Imagen guardada en Cloudinary' : 'Usando el logotipo predeterminado' }}</small></label></div>
          <button v-if="diseno.logoUrl" class="quitar-imagen" type="button" @click="diseno.logoUrl = ''">Usar logotipo predeterminado</button>
          <h3>Contenido</h3>
          <label v-for="campo in camposVista" :key="campo.id" class="check"><input v-model="diseno[campo.id]" type="checkbox" />{{ campo.nombre }}</label>
          <template v-if="vista === 'ticket'"><label class="check"><input v-model="diseno.mostrarDireccion" type="checkbox" />Mostrar dirección del local</label><label v-if="diseno.mostrarDireccion">Dirección<textarea v-model="diseno.direccion" rows="2" maxlength="300" /></label></template>
          <template v-if="vista === 'ticket'">
            <h3>Promoción</h3>
            <label class="check"><input v-model="diseno.mostrarPromocion" type="checkbox" />Incluir cupón promocional al final</label>
            <template v-if="diseno.mostrarPromocion">
              <label>Seleccionar cupón QR<select v-model="diseno.promocionId" @change="seleccionarPromocion"><option value="">Selecciona una promoción</option><option v-for="promo in cupones" :key="promo.id" :value="promo.id">{{ promo.nombre }}</option></select></label>
              <p v-if="!cupones.length" class="estado-cupon">No hay cupones QR disponibles.</p>
              <label>Texto de promoción<textarea v-model="diseno.textoPromocion" rows="2" maxlength="300" placeholder="Ej.: ¡Aprovecha esta promoción en tu próxima visita!" /></label>
            </template>
          </template>
          <label>Mensaje final<textarea v-model="diseno.mensajeFinal" rows="2" maxlength="300" placeholder="Mensaje al pie del comprobante" /></label>
          <label v-if="vista === 'ticket'">Instrucción<textarea v-model="diseno.instruccion" rows="2" maxlength="300" placeholder="Indicación para retirar las prendas" /></label>
          <template v-if="vista === 'ticket'"><div class="opcion-destacada"><label class="check"><input v-model="diseno.mostrarFirma" type="checkbox" />Incluir firma y aceptación del cliente</label></div><label v-if="diseno.mostrarFirma">Texto de aceptación<textarea v-model="diseno.textoAceptacion" rows="2" maxlength="300" /></label><label class="check"><input v-model="diseno.mostrarPoliticas" type="checkbox" />Mostrar condiciones del servicio</label><label>Condiciones del servicio<textarea v-model="politicasTexto" rows="8" placeholder="Una condición por línea" /></label><label>Contacto de las condiciones<textarea v-model="diseno.contactoPolitica" rows="2" maxlength="300" /></label></template>
        </section>
        <section class="panel vista-previa"><header><div><h2>Vista previa</h2></div></header>
          <article class="papel" :style="{ width: diseno.ancho + 'mm', fontSize: diseno.tamanoFuente + 'px' }">
            <header class="ticket-cabecera"><img v-if="diseno.mostrarLogo" :src="diseno.logoUrl || logoTicket" alt="Logo del negocio" class="ticket-logo" /><strong class="marca">LAVANDERÍA SALINAS</strong><span v-if="diseno.mostrarDireccion && diseno.direccion" class="direccion-preview">{{ diseno.direccion }}</span><span>Comprobante de servicio</span><strong class="numero">ORDEN DE SERVICIO · #00042</strong></header>
            <div class="datos"><div v-if="vista === 'ticket'" class="dato"><span>Cliente</span><b>María López</b></div><div v-if="diseno.mostrarTelefono" class="dato"><span>Teléfono</span><b>7000-0000</b></div><div v-if="diseno.mostrarCorreo && vista === 'ticket'" class="dato"><span>Correo</span><b>cliente@correo.com</b></div><div class="dato"><span>Estado de pago</span><b>Anticipo</b></div><div class="dato"><span>Total de prendas</span><b>3</b></div><div v-if="diseno.mostrarEntrega" class="dato"><span>Fecha de entrega</span><b>12 oct. 2026 a las 15:00</b></div><div v-if="diseno.mostrarDetalles" class="dato"><span>Detalles de prendas</span><b>Camisa blanca, pantalón azul</b></div></div>
            <template v-if="vista === 'ticket'"><div v-if="diseno.mostrarServicios" class="servicios"><div class="servicios-titulo"><span>Cant.</span><span>Servicio</span><span v-if="diseno.mostrarPrecios">Total</span></div><div class="fila"><span>2</span><span>Lavado y planchado</span><span v-if="diseno.mostrarPrecios">$12.00</span></div></div><div v-if="diseno.mostrarPago" class="totales"><div class="fila"><span>Subtotal</span><b>$12.00</b></div><div class="fila total"><span>TOTAL</span><b>$12.00</b></div><div class="fila"><span>Saldo pendiente</span><b>$0.00</b></div></div></template>
            <footer class="pie-ticket"><b v-if="diseno.mensajeFinal">{{ diseno.mensajeFinal }}</b><span v-if="vista === 'ticket' && diseno.instruccion">{{ diseno.instruccion }}</span><div v-if="vista === 'ticket' && diseno.mostrarFirma" class="firma-preview">F.____________________________<small>{{ diseno.textoAceptacion }}</small></div></footer>
            <section v-if="vista === 'ticket' && diseno.mostrarPoliticas" class="politica-preview"><h3>Condiciones del servicio</h3><ol><li v-for="(politica, i) in diseno.politicas" :key="i">{{ politica }}</li></ol><small>{{ diseno.contactoPolitica }}</small></section>
            <section v-if="vista === 'ticket' && diseno.mostrarPromocion && promocionSeleccionada" class="promocion-preview"><h3>{{ promocionSeleccionada.nombre }}</h3><p>{{ detallePromocion(promocionSeleccionada) }}</p><p v-if="diseno.textoPromocion">{{ diseno.textoPromocion }}</p><img v-if="qrPreview" :src="qrPreview" alt="QR de la promoción" class="qr-promo-preview" /></section>
          </article>
        </section>
      </div>
    </main>
  </AppShell>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import AppShell from '@/components/AppShell.vue'
import { getApiBaseUrl } from '@/composables/useApiConfig'
import { imprimirTicketOrden, imprimirTicketPrendas, logoTicket } from '@/utils/documentosOrden'
import type { OrdenImprimible } from '@/utils/documentosOrden'
import { crearPayloadCupon } from '@/utils/cuponQr'
import QRCode from 'qrcode'

type Vista = 'ticket' | 'prendas'
type Diseno = { ancho:number; tamanoFuente:number; mostrarLogo:boolean; logoUrl:string; mostrarTelefono:boolean; mostrarCorreo:boolean; mostrarEntrega:boolean; mostrarDetalles:boolean; mostrarServicios:boolean; mostrarPrecios:boolean; mostrarPago:boolean; mensajeFinal:string; instruccion:string; mostrarFirma:boolean; textoAceptacion:string; mostrarPoliticas:boolean; politicas:string[]; contactoPolitica:string; mostrarDireccion:boolean; direccion:string; mostrarPromocion:boolean; promocionId:string; promocionNombre:string; promocionDescripcion:string; promocionTipoDescuento:string; promocionValor:number; promocionFechaFin:string; textoPromocion:string }
type Cupon = { id:string; nombre:string; descripcion:string; tipoDescuento:'porcentaje'|'dinero'; valor:number; vigente:boolean; generarQr:boolean; fechaInicio:string; fechaFin:string }
type CampoToggle = { id:keyof Pick<Diseno,'mostrarLogo'|'mostrarTelefono'|'mostrarCorreo'|'mostrarEntrega'|'mostrarDetalles'|'mostrarServicios'|'mostrarPrecios'|'mostrarPago'>; nombre:string }
const politicasPredeterminadas=['Para retirar las prendas, es indispensable presentar este recibo como único comprobante válido.','La mora por retraso en la entrega inicia después de 2 días calendario de gracia desde la fecha prometida; luego se aplica $0.50 por día.','El plazo para realizar cualquier reclamación sobre el servicio es de 2 días hábiles después de la entrega.','La lavandería no se responsabiliza por pérdidas o daños causados por eventos fortuitos o fuerza mayor, como robos, incendios o desastres naturales, siendo este riesgo asumido por el cliente.','Las prendas no retiradas en un plazo de 30 días serán consideradas abandonadas, liberando a la lavandería de toda responsabilidad sobre ellas.','Si dichas prendas no son reclamadas en un plazo adicional de 10 días (40 días en total desde su disponibilidad), la lavandería se reserva el derecho de donarlas a refugios u organizaciones benéficas sin posibilidad de reclamos futuros.']
const predeterminado:Diseno={ancho:80,tamanoFuente:12,mostrarLogo:true,logoUrl:'',mostrarTelefono:true,mostrarCorreo:true,mostrarEntrega:true,mostrarDetalles:true,mostrarServicios:true,mostrarPrecios:true,mostrarPago:true,mensajeFinal:'¡Gracias por su preferencia!',instruccion:'Presente este ticket al retirar sus prendas.',mostrarFirma:true,textoAceptacion:'Al firmar usted acepta nuestras condiciones y políticas del servicio.',mostrarPoliticas:true,politicas:[...politicasPredeterminadas],contactoPolitica:'Dudas: lavanderiasalinassv@gmail.com · WhatsApp 2497 6699',mostrarDireccion:true,direccion:'3 calle oriente, Barrio Las Flores, Ahuachapán local número dos, situado, Ahuachapán',mostrarPromocion:false,promocionId:'',promocionNombre:'',promocionDescripcion:'',promocionTipoDescuento:'porcentaje',promocionValor:0,promocionFechaFin:'',textoPromocion:'¡Aprovecha esta promoción en tu próxima visita!'}
const plantillaPrendas:Diseno={...predeterminado,ancho:58,tamanoFuente:11,mostrarCorreo:false,mostrarServicios:false,mostrarPrecios:false,mostrarPago:false,mensajeFinal:'',instruccion:'',mostrarFirma:false,mostrarPoliticas:false,politicas:[...politicasPredeterminadas]}
const plantillasPredeterminadas:Record<Vista,Diseno>={ticket:{...predeterminado,politicas:[...politicasPredeterminadas]},prendas:plantillaPrendas}
const disenos=reactive<Record<Vista,Diseno>>({ticket:{...plantillasPredeterminadas.ticket,politicas:[...plantillasPredeterminadas.ticket.politicas]},prendas:{...plantillaPrendas,politicas:[...plantillaPrendas.politicas]}})
const vista=ref<Vista>('ticket'), cargando=ref(false), guardando=ref(false), subiendoImagen=ref(false), error=ref(''), exito=ref(false)
const cupones=ref<Cupon[]>([])
const qrPreview=ref('')
const promocionSeleccionada=computed(()=>cupones.value.find(p=>p.id===diseno.value.promocionId) || (diseno.value.promocionId ? {id:diseno.value.promocionId,nombre:diseno.value.promocionNombre,descripcion:diseno.value.promocionDescripcion,tipoDescuento:diseno.value.promocionTipoDescuento as 'porcentaje'|'dinero',valor:diseno.value.promocionValor,vigente:true,generarQr:true,fechaInicio:'',fechaFin:diseno.value.promocionFechaFin}:null))
const detallePromocion=(promo:Cupon)=>`${promo.descripcion || 'Promoción especial'} · ${promo.tipoDescuento==='porcentaje' ? `${promo.valor}% de descuento` : `$${Number(promo.valor).toFixed(2)} de descuento`}${promo.fechaFin ? ` · Válida hasta ${promo.fechaFin}` : ''}`
const seleccionarPromocion=()=>{const promo=cupones.value.find(p=>p.id===diseno.value.promocionId);if(!promo)return;Object.assign(diseno.value,{promocionNombre:promo.nombre,promocionDescripcion:promo.descripcion,promocionTipoDescuento:promo.tipoDescuento,promocionValor:promo.valor,promocionFechaFin:promo.fechaFin})}
const diseno=computed(()=>disenos[vista.value])
watch(()=>[diseno.value.mostrarPromocion,diseno.value.promocionId] as const,async([mostrar,id])=>{qrPreview.value='';if(mostrar&&id)try{qrPreview.value=await QRCode.toDataURL(crearPayloadCupon(id),{width:180,margin:1,errorCorrectionLevel:'M'})}catch{qrPreview.value=''}} ,{immediate:true})
const politicasTexto=computed({get:()=>diseno.value.politicas.join('\n'),set:(valor:string)=>{diseno.value.politicas=valor.split('\n').slice(0,20)}})
const camposVista=computed<CampoToggle[]>(()=>vista.value==='ticket'?[{id:'mostrarLogo',nombre:'Logo del negocio'},{id:'mostrarTelefono',nombre:'Teléfono del cliente'},{id:'mostrarCorreo',nombre:'Correo del cliente'},{id:'mostrarEntrega',nombre:'Fecha de entrega'},{id:'mostrarDetalles',nombre:'Detalles de prendas'},{id:'mostrarServicios',nombre:'Servicios y cantidades'},{id:'mostrarPrecios',nombre:'Precios'},{id:'mostrarPago',nombre:'Resumen de pago'}] : [{id:'mostrarLogo',nombre:'Logo del negocio'},{id:'mostrarTelefono',nombre:'Teléfono del cliente'},{id:'mostrarEntrega',nombre:'Fecha de entrega'},{id:'mostrarDetalles',nombre:'Descripción de prendas'}])
const api=getApiBaseUrl()+'/disenos-ticket'
const subirLogo=async(event:Event)=>{const archivo=(event.target as HTMLInputElement).files?.[0];if(!archivo)return;const datos=new FormData();datos.append('imagen',archivo);datos.append('tipo',vista.value);subiendoImagen.value=true;error.value='';try{const r=await fetch(api+'/imagen',{method:'POST',body:datos});const resultado=await r.json().catch(()=>null);if(!r.ok)throw new Error(resultado?.error||'No se pudo subir la imagen.');diseno.value.logoUrl=resultado.url;diseno.value.mostrarLogo=true;exito.value=true}catch(e){error.value=e instanceof Error?e.message:'No se pudo subir la imagen.'}finally{subiendoImagen.value=false;(event.target as HTMLInputElement).value=''}}
const cargar=async()=>{cargando.value=true;try{const r=await fetch(api);if(!r.ok)throw new Error('No se pudo cargar el diseño guardado.');const d=await r.json();Object.assign(disenos.ticket,{...predeterminado,...d.ticket});Object.assign(disenos.prendas,{...disenos.prendas,...d.prendas});try{const rc=await fetch(getApiBaseUrl()+'/promociones');if(rc.ok){const lista=await rc.json();const hoy=new Date().toISOString().slice(0,10);cupones.value=(Array.isArray(lista)?lista:[]).filter((p:Cupon)=>p.generarQr&&p.vigente&&p.fechaInicio<=hoy&&p.fechaFin>=hoy)}}catch{cupones.value=[]}}catch(e){error.value=e instanceof Error?e.message:'No se pudo cargar el diseño.'}finally{cargando.value=false}}
const guardarDiseno=async()=>{guardando.value=true;error.value='';exito.value=false;try{const r=await fetch(api,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(disenos)});const d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.error||'No se pudo guardar el diseño.');Object.assign(disenos.ticket,d.ticket);Object.assign(disenos.prendas,d.prendas);exito.value=true}catch(e){error.value=e instanceof Error?e.message:'No se pudo guardar el diseño.'}finally{guardando.value=false}}
const restablecerPredeterminado=async()=>{const plantilla=plantillasPredeterminadas[vista.value];Object.assign(disenos[vista.value],{...plantilla,politicas:[...plantilla.politicas]});await guardarDiseno()}
const imprimirPrueba=async()=>{error.value='';const fecha=new Date();const muestra:OrdenImprimible={numero:'00042',nombreCliente:'María López',items:[{nombre:'Lavado y planchado',cantidad:2,precio:6},{nombre:'Desmanchado',cantidad:1,precio:4}],subtotal:16,total:16,montoRecibido:5,estado:'en_proceso',estadoPago:'anticipo',createdAt:fecha.toISOString(),codigoPais:'+503',telefono:'7000 0000',correo:'cliente@ejemplo.com',cantidadPrendas:3,detallesPrendas:'Camisa blanca, pantalón azul y blusa delicada.',fechaEntrega:fecha.toISOString().slice(0,10),horaEntrega:'15:00',fechaEntregaActiva:true};try{if(vista.value==='ticket')await imprimirTicketOrden(muestra,disenos.ticket);else await imprimirTicketPrendas(muestra,disenos.prendas)}catch(e){error.value=e instanceof Error?e.message:'No se pudo preparar la impresión de prueba.'}}
onMounted(cargar)
</script>

<style scoped>
