or:#a43b3b;cursor:pointer}.vista-previa{background:#f4f7fa}.vista-previa>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.vista-previa header span{color:#74879a;font-size:.78rem}.estado-preview{border-radius:20px;padding:6px 10px;background:#e7eff4}.papel{max-width:100%;min-height:360px;margin:0 auto;padding:20px 14px;background:#fff;border:1px dashed #aaa99f;border-radius:3px;box-shadow:0 8px 25px #1d344722;color:#171717;font-family:'Courier New',monospace;line-height:1.45;overflow-wrap:anywhere}.ticket-cabecera{display:grid;justify-items:center;gap:5px;padding-bottom:12px;border-bottom:1px dashed #777;text-align:center}.ticket-logo{width:27mm;max-width:100%;max-height:18mm;object-fit:contain}.ticket-cabecera .marca{font-size:.82rem;font-weight:900}.ticket-cabecera span{font-size:.72rem}.ticket-cabecera .numero{width:100%;margin-top:3px;padding:6px 3px;border-top:1px solid #333;border-bottom:1px solid #333;font-size:.66rem}.datos{display:grid;gap:0;margin-top:8px}.dato{display:flex;justify-content:space-between;gap:8px;padding:5px 0;border-bottom:1px dashed #c2c2bb;font-size:.78em}.dato span{color:#555}.dato b{text-align:right;overflow-wrap:anywhere}.servicios{margin-top:10px}.servicios-titulo,.fila{display:grid;grid-template-columns:36px 1fr auto;gap:6px}.servicios-titulo{padding-bottom:4px;border-bottom:1px solid #333;font-size:.68em;font-weight:800;text-transform:uppercase}.fila{padding:5px 0;font-size:.76em}.totales{margin-top:6px;border-top:1px dashed #777}.totales .total{font-weight:900;font-size:.9em}.pie-ticket{display:grid;gap:5px;margin-top:12px;padding-top:9px;border-top:1px dashed #777;text-align:center;font-size:.76em}.politica-preview{margin-top:12px;padding-top:8px;border-top:1px dashed #777;font-size:.62em;line-height:1.3}.politica-preview h3{margin:0 0 5px;text-align:center;text-transform:uppercase;font-size:1.05em}.politica-preview ol{margin:0;padding-left:16px}.politica-preview li{margin-bottom:4px}.politica-preview small{display:block;margin-top:6px;text-align:center;overflow-wrap:anywhere}.error,.exito{padding:11px 14px;border-radius:9px}.error{background:#fff0f0;color:#a32d2d}.exito{background:#eaf7ef;color:#1d7041}@media(max-width:800px){.editor-grid{grid-template-columns:1fr}.page-header{align-items:flex-start}.papel{min-height:280px}} 
